c.starter:
#include <stdio.h>

int main(void) {
    char nome[64];
    scanf("%63s", nome);
    printf("Bem-vindo!\n");
    return 0;
}

c.reference:
#include <stdio.h>

int main(void) {
    char nome[64];
    scanf("%63s", nome);
    printf("Bem-vindo, %s!\n", nome);
    return 0;
}

rust.starter:
use std::io;

fn main() {
    let mut nome = String::new();
    io::stdin().read_line(&mut nome).unwrap();
    println!("Bem-vindo!");
}

rust.reference:
use std::io;

fn main() {
    let mut nome = String::new();
    io::stdin().read_line(&mut nome).unwrap();
    println!("Bem-vindo, {}!", nome.trim());
}
